function tokenize(text: string): string[] {
  const lower = text.toLowerCase();
  const tokens: string[] = lower.match(/\b\w+\b/g) ?? [];
  // bigrams
  const out = [...tokens];
  for (let i = 0; i < tokens.length - 1; i++) {
    out.push(tokens[i] + " " + tokens[i + 1]);
  }
  return out;
}

export function classify(text: string): 'reasoning' | 'instant' {
  const tokens = tokenize(text);
  // TF (raw count / total tokens)
  const tf: Record<string, number> = {};
  for (const t of tokens) {
    tf[t] = (tf[t] ?? 0) + 1 / tokens.length;
  }
  let score = BIAS;
  for (const [term, weight] of Object.entries(tf)) {
    if (term in WEIGHTS) score += tf[term] * WEIGHTS[term];
  }
  // sigmoid > 0.5  ⟺  score > 0
  return score > 0 ? 'reasoning' : 'instant';
}
